import{_ as a,o as r,c as e,a0 as l}from"./chunks/framework.DQOulFGV.js";const b=JSON.parse('{"title":"矿车玩法","description":"","frontmatter":{},"headers":[],"relativePath":"minecart.md","filePath":"minecart.md"}'),o={name:"minecart.md"};function i(d,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="矿车玩法" tabindex="-1">矿车玩法 <a class="header-anchor" href="#矿车玩法" aria-label="Permalink to &quot;矿车玩法&quot;">​</a></h1><p>服务器支持把方块放到矿车上，打造<strong>移动工作站</strong>和<strong>移动仓库</strong>：把工作台、铁砧、箱子搬上矿车，推到哪用到哪！</p><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td>手持方块 + <strong>潜行 + 右键</strong>空矿车</td><td>消耗 1 个方块放到矿车上，矿车外观变为该方块</td></tr><tr><td>潜行 + 右键有方块的矿车</td><td>把方块取下（自动进背包）</td></tr><tr><td>右键有方块的矿车</td><td>打开方块对应的功能界面（工作台、铁砧、容器等）</td></tr></tbody></table><blockquote><p>基岩版玩家操作方式相同：潜行键 + 交互键即可。</p></blockquote><h2 id="可以放什么" tabindex="-1">可以放什么 <a class="header-anchor" href="#可以放什么" aria-label="Permalink to &quot;可以放什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>支持</th></tr></thead><tbody><tr><td>工作站</td><td>工作台、砂轮、织布机、制图台、锻造台、切石机、附魔台</td></tr><tr><td>铁砧</td><td>铁砧界面（有耐久损耗，见下）</td></tr><tr><td>容器</td><td>木桶、投掷器、潜影盒及任意带库存的方块，内容实时读写、随矿车保存</td></tr><tr><td>其他方块</td><td>除基岩、屏障等少数方块外均可放置</td></tr></tbody></table><h2 id="特殊矿车" tabindex="-1">特殊矿车 <a class="header-anchor" href="#特殊矿车" aria-label="Permalink to &quot;特殊矿车&quot;">​</a></h2><p>放置箱子、漏斗、熔炉、TNT、命令方块时，矿车会自动转换为对应的<strong>原版特殊矿车</strong>：</p><ul><li>例如把箱子放上矿车 → 变成箱子矿车，潜行取下时矿车还原为普通矿车。</li><li><strong>本服限制</strong>：特殊矿车上的物品<strong>不能取下</strong>（防止复制带库存的非原版物品），内容仍可通过原版界面正常存取。</li></ul><h2 id="容器取下规则" tabindex="-1">容器取下规则 <a class="header-anchor" href="#容器取下规则" aria-label="Permalink to &quot;容器取下规则&quot;">​</a></h2><ul><li>取下木桶/投掷器等容器类方块时，<strong>内容物会掉落到地面</strong>，容器本身以空白物品归还（本服策略）。</li><li>潜影盒不受此限制，与普通方块一样整个取下（内容随盒）。</li></ul><h2 id="铁砧耐久" tabindex="-1">铁砧耐久 <a class="header-anchor" href="#铁砧耐久" aria-label="Permalink to &quot;铁砧耐久&quot;">​</a></h2><ul><li>每次从矿车上取走铁砧修复结果时，铁砧有 <strong>12%</strong> 概率损坏一级（完整 → 损坏 → 报废）。</li><li>报废时铁砧直接消失，不会掉落。</li></ul><h2 id="发射器矿车" tabindex="-1">发射器矿车 <a class="header-anchor" href="#发射器矿车" aria-label="Permalink to &quot;发射器矿车&quot;">​</a></h2><ul><li>把发射器放上矿车，矿车压过<strong>充能激活铁轨</strong>时会随机弹出 1 个物品。</li><li>两次弹出之间约有 2 秒冷却。</li></ul><h2 id="保护联动" tabindex="-1">保护联动 <a class="header-anchor" href="#保护联动" aria-label="Permalink to &quot;保护联动&quot;">​</a></h2><ul><li>矿车放置/取下方块会遵守<strong>领地保护</strong>：在他人领地或联盟领地内，无权建造/破坏时无法操作。</li><li>矿车被破坏时，方块与容器内容会掉落（不丢失、不复制），请放心使用。</li></ul><h2 id="小提示" tabindex="-1">小提示 <a class="header-anchor" href="#小提示" aria-label="Permalink to &quot;小提示&quot;">​</a></h2><ul><li>把工作台和箱子搬上矿车，配合铁轨就能搭建临时补给站。</li><li>发射器矿车可用来做自动发糖机、趣味装置。</li></ul>',20)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
